{

    internal InnerDataAutomationProjectAudioStandardGenerativeFieldFactory GenerativeFieldFactory { get; set; }

    internal InnerDataAutomationProjectAudioStandardExtractionFactory ExtractionFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.AudioStandardOutputConfiguration Create()
    {
        var audioStandardOutputConfigurationResult = CreateAudioStandardOutputConfiguration();
        factoryAction?.Invoke(audioStandardOutputConfigurationResult);

        return audioStandardOutputConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.AudioStandardOutputConfiguration CreateAudioStandardOutputConfiguration()
    {
        var audioStandardOutputConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.AudioStandardOutputConfiguration();

        return audioStandardOutputConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.AudioStandardOutputConfiguration result)
    {
        base.CreateChildren(result);

        result.GenerativeField ??= GenerativeFieldFactory?.Build();
        result.Extraction ??= ExtractionFactory?.Build();
    }

} // End Of Class

